-- OCN-48201 | Chinedu Okafor (placed)
insert into public.orders (order_number, customer_name, phone, address, state, zone, payment_method, subtotal, delivery_fee, total, status, placed_at, cancelled_at, cancelled_from)
values (
  'OCN-48201', 'Chinedu Okafor', '0803 123 4567', '18 Adeola Odeku Street, Victoria Island',
  'Lagos', 'A', 'paystack', 320000, 2500, 322500,
  'placed', now() - interval '3 hours',
  null,
  null
)
on conflict (order_number) do nothing;

insert into public.order_items (order_number, name, unit_price, quantity, line_total)
select v.* from (values
    ('OCN-48201', 'Samsung Galaxy A54', 320000, 1, 320000)
  ) as v(order_number, name, unit_price, quantity, line_total)
where not exists (
  select 1 from public.order_items where order_number = 'OCN-48201'
);

insert into public.order_events (order_number, status, note, created_at)
select * from (values
    ('OCN-48201', 'placed', 'Order placed on the storefront', now() - interval '3 hours')
  ) as v(order_number, status, note, created_at)
where not exists (
  select 1 from public.order_events where order_number = 'OCN-48201'
);

